with Base as (select * from web_events where page <> '/product'), Summary as (select case when duration_sec >= 397 then 'high' when duration_sec >= 215 then 'mid' else 'low' end as duration_sec_bucket, round((100 * sum(case when event_type = 'search' then 1 else 0 end)) / count(*), 1) as pct_search from Base group by case when duration_sec >= 397 then 'high' when duration_sec >= 215 then 'mid' else 'low' end) select * from Summary order by duration_sec_bucket, pct_search desc limit 3;
